package multichat_udp;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.text.SimpleDateFormat;
import java.util.Date;

/**
 * Đóng gói thông điệp truyền qua giao thức UDP Multicast.
 * Sử dụng ByteArrayOutputStream / DataOutputStream khi gửi
 * và ByteArrayInputStream / DataInputStream khi nhận (theo tài liệu Chap_6_Socket_UDP_2, slide 29-30).
 */
public class ChatMessage implements Serializable {
    public static final int MAGIC_NUMBER = 0x4D435550; // "MCUP"
    private static final SimpleDateFormat TIME_FORMAT = new SimpleDateFormat("HH:mm:ss");

    private MessageType type;
    private String senderId;
    private String senderName;
    private String content;
    private String targetUser; // Dùng khi gửi tin nhắn riêng (Whisper)
    private long timestamp;

    public ChatMessage(MessageType type, String senderId, String senderName, String content, String targetUser, long timestamp) {
        this.type = type;
        this.senderId = senderId != null ? senderId : "";
        this.senderName = senderName != null ? senderName : "Ẩn danh";
        this.content = content != null ? content : "";
        this.targetUser = targetUser != null ? targetUser : "";
        this.timestamp = timestamp > 0 ? timestamp : System.currentTimeMillis();
    }

    public MessageType getType() {
        return type;
    }

    public String getSenderId() {
        return senderId;
    }

    public String getSenderName() {
        return senderName;
    }

    public String getContent() {
        return content;
    }

    public String getTargetUser() {
        return targetUser;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public String getFormattedTime() {
        return TIME_FORMAT.format(new Date(timestamp));
    }

    /**
     * Chuyển đối tượng ChatMessage thành mảng byte để đóng gói vào DatagramPacket.
     * Áp dụng kỹ thuật ByteArrayOutputStream & DataOutputStream.
     */
    public byte[] toBytes() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (DataOutputStream dos = new DataOutputStream(baos)) {
            dos.writeInt(MAGIC_NUMBER);
            dos.writeByte(type.getCode());
            dos.writeUTF(senderId);
            dos.writeUTF(senderName);
            dos.writeUTF(content);
            dos.writeUTF(targetUser);
            dos.writeLong(timestamp);
            dos.flush();
            return baos.toByteArray();
        }
    }

    /**
     * Giải mã dữ liệu từ DatagramPacket thành đối tượng ChatMessage.
     * Áp dụng kỹ thuật ByteArrayInputStream & DataInputStream (Slide 30).
     * Có fallback xử lý chuỗi ký tự thô nếu gói tin gửi từ ứng dụng UDP đơn giản (Slide 35).
     */
    public static ChatMessage fromBytes(byte[] data, int offset, int length) {
        if (data == null || length <= 0) {
            return null;
        }

        try {
            ByteArrayInputStream bais = new ByteArrayInputStream(data, offset, length);
            DataInputStream dis = new DataInputStream(bais);

            if (length >= 4) {
                int magic = dis.readInt();
                if (magic == MAGIC_NUMBER) {
                    byte typeCode = dis.readByte();
                    MessageType type = MessageType.fromCode(typeCode);
                    String senderId = dis.readUTF();
                    String senderName = dis.readUTF();
                    String content = dis.readUTF();
                    String targetUser = dis.readUTF();
                    long timestamp = dis.readLong();

                    return new ChatMessage(type, senderId, senderName, content, targetUser, timestamp);
                }
            }
        } catch (Exception ignored) {
            // Nếu không đúng định dạng giao thức MCUP, rơi vào fallback chuỗi thô bên dưới
        }

        // Fallback: gói tin văn bản thông thường từ client UDP cơ bản
        String rawText = new String(data, offset, length, StandardCharsets.UTF_8).trim();
        return new ChatMessage(MessageType.CHAT, "raw", "UDP Client", rawText, "", System.currentTimeMillis());
    }

    // Các hàm khởi tạo tiện ích (Factory methods)
    public static ChatMessage createJoin(String senderId, String senderName) {
        return new ChatMessage(MessageType.JOIN, senderId, senderName, senderName + " đã tham gia phòng chat.", "", System.currentTimeMillis());
    }

    public static ChatMessage createLeave(String senderId, String senderName) {
        return new ChatMessage(MessageType.LEAVE, senderId, senderName, senderName + " đã rời phòng chat.", "", System.currentTimeMillis());
    }

    public static ChatMessage createChat(String senderId, String senderName, String content) {
        return new ChatMessage(MessageType.CHAT, senderId, senderName, content, "", System.currentTimeMillis());
    }

    public static ChatMessage createWhisper(String senderId, String senderName, String targetUser, String content) {
        return new ChatMessage(MessageType.WHISPER, senderId, senderName, content, targetUser, System.currentTimeMillis());
    }

    public static ChatMessage createHeartbeat(String senderId, String senderName) {
        return new ChatMessage(MessageType.HEARTBEAT, senderId, senderName, "", "", System.currentTimeMillis());
    }
}

MessageType.java:
package multichat_udp;

public enum MessageType {
    JOIN((byte) 1),
    LEAVE((byte) 2),
    CHAT((byte) 3),
    HEARTBEAT((byte) 4),
    WHISPER((byte) 5);

    private final byte code;

    MessageType(byte code) {
        this.code = code;
    }

    public byte getCode() {
        return code;
    }

    public static MessageType fromCode(byte code) {
        for (MessageType t : values()) {
            if (t.code == code) return t;
        }
        return CHAT;
    }
}

