package multichat_udp;

import javax.swing.SwingUtilities;
import javax.swing.UIManager;

/**
 * Lớp khởi chạy chính của ứng dụng Multichat UDP.
 * Có thể chạy dưới dạng giao diện đồ họa (GUI) mặc định,
 * hoặc chế độ dòng lệnh (CLI): java -cp build/classes multichat_udp.Multichat_UDP cli [tên] [ip] [port]
 */
public class Multichat_UDP {

    public static void main(String[] args) {
        if (args.length > 0 && "cli".equalsIgnoreCase(args[0])) {
            new MultichatCLI().start(args);
            return;
        }

        // Chạy giao diện đồ họa GUI
        try {
            UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());
        } catch (Exception ignored) {
        }

        SwingUtilities.invokeLater(() -> {
            MultichatUI ui = new MultichatUI();
            ui.setVisible(true);
        });
    }
}

